	log.SetOutput(io.Discard)
	code := m.Run()
	log.SetOutput(os.Stderr)
	os.Exit(code)
}

// The logged-in view has a single button, on the field the login form uses for
// the URL.
const fieldLogoutButton = fieldToken

// fakeStorage records what the view asks of the secret store.
type fakeStorage struct {
	token     string
	loadErr   error
	saved     map[string]string
	deleted   []string
	loadCalls []string
}

func newFakeStorage() *fakeStorage {
// into the host's secret manager, and nowhere else (§3.9).
const (
	fieldToken = REDACTED
	fieldSubmit

	lastField = fieldSubmit
)

// Model represents the GitLab authentication view
type Model struct {
	config *config.Config
	// There is no URL input. forge.url is configuration and the configuration
	// view owns it; this view owns the token, which is a secret, and the act of
	// logging in. Both used to write the URL, so neither was authoritative.
	tokenInput textinput.Model

	// secrets is where the token goes, and what to tell the user about it.
	secrets credentials.Selection

	// notices report what the migration off plaintext configuration did, if
	// anything. Shown once, on the view that owns the token.
	notices []string

	currentField int

	authenticated bool // True if the user is authenticated
	// user is the signed-in user, zero when there is none — m.authenticated is
	// the flag, and a second way to ask is how the two came to disagree.
	user forge.User

	authenticating bool
	spinner        spinner.Model
	error          string
	success        string
	warning        string // Non-blocking warning (e.g. credentials save failure)

	// footer carries the messages other parts of the app post to this view (Rule 128).
	footer components.FooterMessage

	width  int
	height int
