func TestMain(m *testing.M) {
	log.SetOutput(io.Discard)

	home, err := os.MkdirTemp("", "devdesk-setup-test")
	if err != nil {
		log.SetOutput(os.Stderr)
		panic(err)
	}
	_ = os.Setenv("HOME", home)
	_ = os.Setenv("USERPROFILE", home)

	code := m.Run()

	_ = os.RemoveAll(home)
	log.SetOutput(os.Stderr)
	os.Exit(code)
}

// isolateHome gives the test a HOME of its own. The one TestMain sets lives as
// long as the process, so under -count=N a test met the files its own previous
// run had written: the remote themes already downloaded, so the fetch added
// none (DEVDESK-38, the same defect as DEVDESK-36 in internal/app). Every test
// that writes under HOME calls it, which keeps TestMain's HOME empty for the
// tests that only read it.
func isolateHome(t *testing.T) {
	t.Helper()
	home := t.TempDir()
	t.Setenv("HOME", home)
	t.Setenv("USERPROFILE", home)
}

// feed applies messages to the model in order.
func feed(t *testing.T, m Model, msgs ...tea.Msg) Model {
	t.Helper()
	for _, msg := range msgs {
		next, _ := m.Update(msg)
		m = next.(Model)
	}
	return m
}

// past advances the model past the font check and, optionally, sets a
// context name and answers it — the two steps almost every other test needs
// out of the way before it can exercise the step it actually cares about.
func past(t *testing.T, m Model, name string) Model {
	t.Helper()
	m = feed(t, m, testutil.Key("enter")) // font check -> context name
	if name != "" {
		m.contextNameInput.SetValue(name)
	}
	m = feed(t, m, ContextExistsMsg{Exists: false}) // as if submit+check already ran
	return m
}

}

// Init starts the cursor blink, the only thing the wizard needs on launch.
func (m Model) Init() tea.Cmd {
	return textinput.Blink
}

// Update is the single Elm-architecture entry point (Rule 110): every field
// mutation happens here, never inside a Cmd.
func (m Model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		m.width = msg.Width
		m.height = msg.Height
		return m, nil

	case tea.KeyPressMsg:
		return m.handleKeyMsg(msg)

	case spinner.TickMsg:
		var cmd tea.Cmd
		m.spinner, cmd = m.spinner.Update(msg)
		return m, cmd

	case components.ConfirmModalYesMsg:
		return m.handleConfirmYes()

	case components.ConfirmModalNoMsg:
		return m.handleConfirmNo()

	case ContextExistsMsg:
		return m.handleContextExists(msg)

	case RemoteThemesFetchedMsg:
		return m.handleRemoteThemesFetched(msg)

	case SecretBackendCheckedMsg:
		return m.handleSecretBackendChecked(msg)

	case ContainerEngineCheckedMsg:
		return m.handleContainerEngineChecked(msg)

	case TokenValidatedMsg:
		return m.handleTokenValidated(msg)

	case ContextSavedMsg:
		return m.handleContextSaved(msg)

	case CurrentContextSetMsg:
		return m.handleCurrentContextSet(msg)
	}

	if m.footer.Handle(msg) {
		return m, nil
	}
	return m, nil
}

	}
	return []string{"private", "internal", "public"}
}

func (m Model) updateFocusedInput(msg tea.KeyPressMsg) (tea.Model, tea.Cmd) {
	var cmd tea.Cmd
	switch m.step {
	case stepContextName:
		m.contextNameInput, cmd = m.contextNameInput.Update(msg)
	case stepForgeURL:
		m.forgeURLTouched = true
		m.forgeURLInput, cmd = m.forgeURLInput.Update(msg)
	case stepForgeNamespace:
		m.forgeNamespaceInput, cmd = m.forgeNamespaceInput.Update(msg)
	case stepForgeToken:
		m.forgeTokenInput, cmd = m.forgeTokenInput.Update(msg)
	}
	return m, cmd
}

func wrap(i, n int) int {
	if n <= 0 {
		return 0
	}
	return ((i % n) + n) % n
}

func indexOf(opts []string, v string) int {
	for i, o := range opts {
		if o == v {
			return i
		}
	}
	return -1
}

// submitContextName validates the name and starts the async chain's first
// link: does a context by this name already exist?
func (m Model) submitContextName() (tea.Model, tea.Cmd) {
	name := strings.TrimSpace(m.contextNameInput.Value())
	if err := config.ValidateNewContextName(name); err != nil {
		if errors.Is(err, config.ErrReservedContextName) {
			return m, m.footer.Error("\"" + name + "\" is reserved — choose another name")
		}
		return m, m.footer.Error(err.Error())
	}
	m.contextNameInput.SetValue(name)
	m.pending = "Checking context name..."
	return m, tea.Batch(m.spinner.Tick, checkContextExistsCmd(name))
}

func TestForgeURLIsPrefilledButNotOverwrittenOnceTouched(t *testing.T) {
	m := New()
	if m.forgeURLInput.Value() == "" {
		t.Fatal("forgeURLInput is empty on a new model; expected the GitLab example URL")
	}
	m.forgeURLInput.SetValue("")

	m = past(t, m, "staging")
	m.step = stepForgeURL
	m.updateFocus()

	m = feed(t, m, testutil.Type("https://git.internal")...)
	if !m.forgeURLTouched {
		t.Fatal("forgeURLTouched was not set after typing into the field")
	}

	m = feed(t, m, testutil.Key("esc")) // forgeURL -> forgeType
	if m.step != stepForgeType {
		t.Fatalf("step = %d, want stepForgeType", m.step)
	}
	m = feed(t, m, testutil.Key("right")) // gitlab -> github

	if m.forgeURLInput.Value() != "https://git.internal" {
		t.Errorf("forgeURLInput.Value() = %q, want the user's own value preserved", m.forgeURLInput.Value())
	}
}

func TestTokenValidationFailureReturnsToTheTokenStepWithAFooterError(t *testing.T) {
	m := New()
	m.step = stepForgeToken
	m.pending = "Validating token..."
