	// Topology sub-model messages
	case ifaceDataMsg:
		var cmd tea.Cmd
		m.interfacesModel, cmd = m.interfacesModel.update(msg)
		return m, cmd

	case tea.KeyPressMsg:
		return m.handleKey(msg)
	}

	// Each tab holds its own footer, so an expiry has to be offered to all
	// four: the timer fires wherever the user has since navigated.
	m.footer.Handle(msg)
	m.portsModel.footer.Handle(msg)
	m.interfacesModel.footer.Handle(msg)
	m.forwardModel.footer.Handle(msg)
	return m, nil
}

// routeConfirm hands a confirmation answer to the tab that put the modal up.
		// can name.
		log.Printf("ERROR [netdiag] target became invalid mid-run: %v", err)
		m.state = StateResults
		return m, m.footer.Error("Run stopped — the target is no longer valid")
	}
	return m, runStageCmd(m.runGen, tg, m.checkSettings(), msg.next, m.results)
}

func (m *Model) handleKey(msg tea.KeyPressMsg) (*Model, tea.Cmd) {
	// A filter bar in edit mode claims every key before anything else, or a
	// query cannot contain the letters the view binds.
	if m.activeTab == tabDiagnostics && m.filterBar.InEditMode() {
		var cmd tea.Cmd
		m.filterBar, cmd = m.filterBar.Update(msg)
		m.rebuildChecksTable()
		return m, cmd
	}

	// Tab / Shift+Tab cycles between the three tabs (Rule 135)
	switch msg.String() {
	case "tab":
		m.activeTab = (m.activeTab + 1) % tabCount
		return m, nil
	case "shift+tab":
		m.activeTab = (m.activeTab + tabCount - 1) % tabCount
		return m, nil
	}

	// Route to active tab
	if m.activeTab == tabPorts {
		var cmd tea.Cmd
		m.portsModel, cmd = m.portsModel.update(msg)
		return m, cmd
	}
	if m.activeTab == tabInterfaces {
		var cmd tea.Cmd
		m.interfacesModel, cmd = m.interfacesModel.update(msg)
		return m, cmd
	}
	if m.activeTab == tabForward {
		var cmd tea.Cmd
		m.forwardModel, cmd = m.forwardModel.update(msg)
		return m, cmd
	}

	switch m.state {
	case StateInput:
		return m.handleKeyInput(msg)
	case StateRunning:
		return m.handleKeyRunning(msg)
	case StateResults:
		return m.handleKeyResults(msg)
	case StateDetails:
		return m.handleKeyDetails(msg)
	}
	return m, nil
}

// handleKeyRunning cancels the run. The stage in flight is awaited rather than
// interrupted — it is a network read that will time out on its own — and its
// result is discarded by the generation counter.
func (m *Model) handleKeyRunning(msg tea.KeyPressMsg) (*Model, tea.Cmd) {
	if msg.String() != "esc" {
		return m, nil
	}
	m.runGen++
	m.state = StateResults
	m.verdict = netcheck.Summarize(m.results.All())
	m.rebuildChecksTable()
	return m, m.footer.Warn("Run cancelled — showing what completed")
}

func (m *Model) handleKeyInput(msg tea.KeyPressMsg) (*Model, tea.Cmd) {
	switch msg.String() {
	case "down":
		m.moveFocus(1)
		return m, nil
	case "up":
		m.moveFocus(-1)
		return m, nil
	case "enter":
		// enter runs from anywhere in the form: with three fields and one
		// button there is nothing else it could mean, and making the user walk
		// to the button first is a step that buys nothing.
		return m.StartRun()
	case "esc":
		return m, nil
	}
	return m.updateActiveInput(msg)
}

func (m *Model) moveFocus(delta int) {
	switch m.focusedField {
	case fieldTarget:
		m.targetInput.Blur()
	case fieldPort:
		m.portInput.Blur()
	case fieldDNSServer:
		m.dnsServerInput.Blur()
	}

	m.focusedField = (m.focusedField + delta + fieldCount) % fieldCount

	switch m.focusedField {
	case fieldTarget:
		m.targetInput.Focus()
	case fieldPort:
		m.portInput.Focus()
	case fieldDNSServer:
		m.dnsServerInput.Focus()
	}
}

func (m *Model) updateActiveInput(msg tea.KeyPressMsg) (*Model, tea.Cmd) {
	var cmd tea.Cmd
	switch m.focusedField {
	case fieldTarget:
		m.targetInput, cmd = m.targetInput.Update(msg)
	case fieldPort:
		m.portInput, cmd = m.portInput.Update(msg)
	case fieldDNSServer:
		m.dnsServerInput, cmd = m.dnsServerInput.Update(msg)
	}
	return m, cmd
}

