// The mode a member ends up with is settled once, when the group resolves —
// there is no second place that could disagree with it.
func TestCachedMembersCarryTheirGroupsMode(t *testing.T) {
	b := newRegistryBrowser(
		[]config.RegistryItem{{
			URL: "registry.example.com", Alias: "prod", Slug: "prod",
			Kind: config.KindGroup, AuthMode: config.AuthAnonymous,
		}},
		map[string]cache.RegistryGroupEntry{"prod": {Members: []cache.RegistryGroupMember{
			{Alias: "hosted", URL: "registry.example.com/repository/docker-hosted"},
		}}},
		nil, 120, 30,
	)

	if len(b.entries) != 1 {
		t.Fatalf("got %d entries, want the one member", len(b.entries))
	}
	if b.entries[0].authMode != config.AuthAnonymous {
		t.Errorf("the member resolved as %q, want its anonymous group's mode", b.entries[0].authMode)
	}
	if b.entries[0].ParentSlug != "prod" {
		t.Errorf("ParentSlug = %q, want the group it came from", b.entries[0].ParentSlug)
	}
}

// ── The group cache (§3.8 step 3) ────────────────────────────────────────────

// openMultiRegistryBrowser opens the multi-registry browser (triggered by 'b' on Images tab).
func (m Model) openMultiRegistryBrowser() (tea.Model, tea.Cmd) {
	if len(m.registries) == 0 {
		return m, m.footer.Warn("No registries configured — add one in the Registries tab")
	}
	// Config plus cache, read here and now: no network, no waiting, no state
	// that ignores esc (D13).
	m.registryBrowser = newRegistryBrowser(m.registries, m.groupCache, m.browserDeselected, m.width-2, m.height)
	m.registryBrowser.SetScanCache(m.scanCache)
	m.registryBrowser.SetJobs(m.jobs, m.failures, m.contextName)
	return m, nil
}

// closeMultiRegistryBrowser drops the browser, remembering what the user
// unchecked so the next visit opens on the same selection.
func (m Model) closeMultiRegistryBrowser() (tea.Model, tea.Cmd) {
